class Solution {
    public int majorityValue(int[] readings) {
        int n = readings.length;
        for (int r : readings) {
            int c = 0;
            for (int x : readings) if (x == r) c++;
            if (c * 2 > n) return r;
        }
        return readings[0];
    }
}

