static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

int majorityValue(int* readings, int readingsSize) {
    int* s = malloc(readingsSize * sizeof(int));
    memcpy(s, readings, readingsSize * sizeof(int));
    qsort(s, readingsSize, sizeof(int), cmpInt);
    int answer = s[readingsSize / 2];
    free(s);
    return answer;
}

