// A small hash map from a value to its count: open addressing, linear probing.
typedef struct { int key; int count; bool used; } Slot;

static unsigned slotOf(int key, unsigned mask) {
    unsigned long long h = (unsigned long long) (long long) key * 0x9E3779B97F4A7C15ULL;
    return (unsigned) (h >> 32) & mask;
}

int majorityValue(int* readings, int readingsSize) {
    unsigned cap = 1;
    while (cap < 2u * readingsSize) cap <<= 1;
    Slot* count = calloc(cap, sizeof(Slot));
    int answer = readings[0];
    for (int i = 0; i < readingsSize; i++) {
        int r = readings[i];
        unsigned s = slotOf(r, cap - 1);
        while (count[s].used && count[s].key != r) s = (s + 1) & (cap - 1);
        count[s].key = r;
        count[s].used = true;
        if (++count[s].count * 2 > readingsSize) { answer = r; break; }
    }
    free(count);
    return answer;
}

